    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
for i in [1,2,3,4,5]:
    gi=G[f'Demo pair {i} input']; go=G[f'Demo pair {i} output']
    si={(r,c) for r,row in enumerate(gi) for c,v in enumerate(row) if v}
    so={(r,c) for r,row in enumerate(go) for c,v in enumerate(row) if v}
    bot=max(r for r,c in si)
    pred={(r,c-(bot-r)) for r,c in si if c-(bot-r)>=0}
    print(i, pred==so, len(si),len(so))
ti=G['Test input']; print(ti and ti[3])

def f(gi):
    H=len(gi); W=len(gi[0])
    cells={(r,c) for r,row in enumerate(gi) for c,v in enumerate(row) if v}
    bot=max(r for r,c in cells)
    out=set()
    for r,c in cells:
        cc=c-(bot-r)
        if cc>=0: out.add((r,cc))
    return [[1 if (r,c) in out else 0 for c in range(W)] for r in range(H)]
pred=f(G['Test input'])
import json; print(json.dumps(pred))
